node --input-type=module <<'JS'
import assert from 'node:assert/strict';
import {mkdtemp,mkdir,writeFile,readFile,readdir,rm} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {createEvidenceRedactor} from './.local/skills-mcp-migration-live/redact-evidence.mjs';
import {inventoryEvidence,cleanupEvidence} from './.local/skills-mcp-migration-live/cleanup-evidence.mjs';
import {apply} from './.local/skills-mcp-migration-live/llm-observer.mjs';
const payload={type:'tool/result',data:{properties:{name:'fixture'},capability:'fixture-credential'}};
const tool={name:'test',parameters:{type:'object',properties:{token:{type:'string'},capability:{type:'string'}},required:['token']}};
const redactor=createEvidenceRedactor();
const safe=redactor.redact(payload);
assert.equal(safe.data.capability,'fixture-credential');
assert.deepEqual(redactor.redact({tools:[tool]}),{tools:[tool]});
console.log('R1 reproduced: runtime credential survives; real tool schema control is preserved');
const root=await mkdtemp(join(tmpdir(),'independent-redaction-review-'));
try {
 const controller=join(root,'controller'),isolated=join(controller,'isolated-profiles','fixture'),desktop=join(controller,'desktop','fixture-run');
 await mkdir(isolated,{recursive:true});await mkdir(desktop,{recursive:true});
 const file=join(desktop,'100-id-collect.json');
 await writeFile(file,JSON.stringify({token:'fixture-active-secret'}));
 await writeFile(join(isolated,'state.json'),JSON.stringify({status:'running',runId:'fixture-run'}));
 await writeFile(join(controller,'execution-index.json'),JSON.stringify({collect:file}));
 const inv=await inventoryEvidence(controller);
 assert.equal(inv.files.includes(file),true);
 assert.equal(inv.controlFiles.includes(join(isolated,'state.json')),false);
 const preview=await cleanupEvidence({controller});
 assert.equal(preview.files.some(entry=>entry.path===file&&entry.replacements>0),true);
 assert.equal(preview.excluded.length,0);
 console.log('R2 reproduced: evidence belonging to running isolated state remains eligible for cleanup');
 const directory=join(root,'observer');let hook;
 apply({on(_e,h){hook=h;}},{evidenceDirectory:directory,allowed:[{provider:'fixture',model:'fixture'}]});
 const opts={provider:'fixture',model:'fixture',messages:[]};
 const a=hook(opts,()=> (async function*(){yield {type:'text-delta',index:0,text:'CLI_CAPABILITY=fixture-interleaved-secret\n'};})());
 await a.next();
 for await(const x of hook(opts,()=> (async function*(){yield {type:'text-delta',index:0,text:'repeat fixture-interleaved-secret'};})())){}
 const bFile=(await readdir(directory))[0];
 assert.equal((await readFile(join(directory,bFile),'utf8')).includes('fixture-interleaved-secret'),true);
 await a.next();
 assert.equal((await readdir(directory)).length,2);
 assert.equal((await readFile(join(directory,bFile),'utf8')).includes('fixture-interleaved-secret'),true);
 console.log('R3 reproduced: same observer, A emits complete env assignment, B completes, A completes, B evidence retains secret');
} finally {await rm(root,{recursive:true,force:true});}
